/* Byte sum of the saved DS block into the slot record. */
void opeu_save_checksum(uint8_t ds[65536], uint8_t slot) {
  BYTE_POINTER a;
  uint16_t     b;
  b = 0;
  for (a = FIRST_BYTE; a <= LAST_BYTE; a++)
    b += BYTE_AT(a);
  SLOTS[slot].checksum = b;
}

/* First save: a new file with twenty slot records and twenty game copies. */
void opeu_save_create(uint8_t ds[65536], HostEvent event) {
  uint8_t   a;
  SaveSlot* b;
  int       c;
  SCREEN_RESET();
  ATTRIBUTE(4);
  DISK_RESET();
  UI_TEXT(FRAMED(32, 188, TXT("Saving...", 0xb04b)));
  DISK_RESET();
  b                   = SLOTS;
  b->scenario         = SCENARIO;
  SLOTS[0].delivery   = DELIVERY;
  SLOTS[0].year       = YEAR;
  SLOTS[0].month      = MONTH;
  SLOTS[0].day        = DAY;
  SLOTS[0].hour       = HOUR;
  SLOTS[0].control[0] = CONTROL0;
  SLOTS[0].control[1] = CONTROL1;
  SAVE_CHECKSUM(0);
  c = CREATE(TXT("Savedata", 0xb055));
  for (a = 0; a < 20; a++) {
    if (a == 0)
      b->scenario = SCENARIO;
    else
      b->scenario = 6;
    WRITE(c, 0xd006, 12);
  }
  SAVE_UNREBASE();
  for (a = 0; a < 20; a++)
    WRITE(c, 0x42, SAVE_BYTES);
  SAVE_REBASE();
  CLOSE(c);
  if (EXISTS(TXT("Savedata", 0xb05e))) {
    UI_TEXT(FRAMED(31, 188, TXT("Game Saved.", 0xb067)));
    UI_WAIT(15);
    ATTRIBUTE(0);
  }
}

/* Framed prompt at text column x, pixel row y; returns the text. */
uint16_t opeu_save_prompt_box(uint8_t ds[65536], HostEvent event, uint16_t x,
                              uint16_t y, uint16_t text) {
  uint16_t a;
  BOX(x - 1, y - 4, a = LENGTH(text) + 2, 24, 1);
  OUTLINE((x - 1) * 8, y - 4, (x + a) * 8 - 9, y + 19, 7);
  POSITION(x, y);
  return text;
}

